'&N &N Information . . :   &1 journal entries have not been exported b-
ecause of incomplete data or because of journal parameter ''MINENTDTA'-
'.'                                                                   +
                ) +
                SEV(00) +
                FMT( +
                    (*CHAR 0010) +
                ) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /*-------------------------------------------------------------*/
     /*   Cmd-ADDMSGD für Message-ID :   USR0019                    */
     /* Renamed field or record format &1 to &2.                    */
     /*-------------------------------------------------------------*/

             ADDMSGD +
                MSGID(USR0019) +
                MSGF(&LI/EXPJRNE) +
