                SECLVL(+
'&N &N Information . . :   The program tried to access memory outside -
the specified boundaries. Please report that error to the developer.' +
                ) +
                SEV(00) +
     /*   Keine Ersatzvariablen definiert!                          */ +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /*-------------------------------------------------------------*/
     /*   Cmd-ADDMSGD für Message-ID :   USR0021                    */
