offset = 0;
dow offset < %size(i_bytes); pSource = %addr(i_bytes) + offset; cvthc(%addr(chunk) : pSource : %size(chunk)); if (ipv6 <> ''); ipv6 = ipv6 + ':'; endif; ipv6 = ipv6 + chunk; offset = offset + 2; enddo;
