/END-FREE P E * *==================================================================== * *** private *** * Map Send data queue, has key (Q QK) journal entry * to common data queue journal entry data structure. *==================================================================== P mapJrnE_Q_QK... P B D PI D i_pData * const D i_length 10I 0 const * * Local fields D tmpJrnEType_q_qk... D DS likeds(jrnEType_q_qk_t ) D jrnEType_q_qk... D DS likeds(jrnEType_q_qk_t ) D based(i_pData) D jrnEType_q... D DS likeds(jrnEType_q_t ) D based(i_pData) D key_q S 65535A based(pKey_q ) D key_qk S 65535A based(pKey_qk ) D data_q S 65535A based(pData_q ) D data_qk DS likeds(dtaQ_data_t ) based(pData_qk ) D tmpKey S 65535A based(pTmpKey ) D tmpData DS likeds(dtaQ_data_t ) based(pTmpData ) D sysInf_1_qk S 16A based(pSysInf_1_qk ) D tmpSysInf_1 S 16A inz D sysInf_2_qk S 16A based(pSysInf_2_qk ) D tmpSysInf_2 S 16A inz * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
// Save journal data tmpJrnEType_q_qk = %subst(jrnEType_q_qk: 1: %len(tmpJrnEType_q_qk));
// System Information 1 pSysInf_1_qk = %addr(jrnEType_q_qk) + %size(jrnEType_q_qk) + jrnEType_q_qk.keyLength; tmpSysInf_1 = sysInf_1_qk;
// System Information 2 pSysInf_2_qk = %addr(jrnEType_q_qk) + %size(jrnEType_q_qk) + jrnEType_q_qk.keyLength + %size(sysInf_1_qk); tmpSysInf_2 = sysInf_2_qk;
// Save key if (jrnEType_q_qk.keyLength > 0); pTmpKey = %alloc(tmpJrnEType_q_qk.keyLength); pKey_qk = %addr(jrnEType_q_qk) + %size(jrnEType_q_qk); %subst(tmpKey: 1: tmpJrnEType_q_qk.keyLength) = %subst(key_qk: 1: jrnEType_q_qk.keyLength); else; pTmpKey = *NULL; endif;
// Save data if (jrnEType_q_qk.dataLength > 0); pTmpData = %alloc(tmpJrnEType_q_qk.dataLength); pData_qk = %addr(jrnEType_q_qk) + jrnEType_q_qk.ofsData; %subst(tmpData: 1: tmpJrnEType_q_qk.dataLength) = %subst(data_qk: 1: tmpJrnEType_q_qk.dataLength); else; pTmpData = *NULL; endif;
// Map journal data clear jrnEType_q;
jrnEType_q.sysInf_1 = tmpSysInf_1; jrnEType_q.sysInf_2 = tmpSysInf_2; jrnEType_q.sysInf_3 = *ALLx'00'; jrnEType_q.order = ''; jrnEType_q.keyLength = tmpJrnEType_q_qk.keyLength; jrnEType_q.dataLength = tmpJrnEType_q_qk.dataLength - %size(dtaQ_data_t.apiInf); if (pTmpData = *NULL); jrnEType_q.apiInf = *ALLx'00'; else; jrnEType_q.apiInf = tmpData.apiInf; endif;
pKey_q = %addr(jrnEType_q) + %size(jrnEType_q); // key enforceBoundaries(i_pData: i_length: pKey_q: jrnEType_q.keyLength); %subst(key_q: 1: jrnEType_q.keyLength) = %subst(tmpKey: 1: tmpJrnEType_q_qk.keyLength);
pData_q = %addr(jrnEType_q) + %size(jrnEType_q) + // data jrnEType_q.keyLength; enforceBoundaries(i_pData: i_length: pData_q: jrnEType_q.dataLength); %subst(data_q: 1: jrnEType_q.dataLength) = %subst(tmpData.value: 1: tmpJrnEType_q_qk.dataLength);
// Free memory if (pTmpKey <> *NULL); dealloc(N) pTmpKey; endif; if (pTmpData <> *NULL); dealloc(N) pTmpData; endif;
/END-FREE P E * *==================================================================== * *** private *** * Map Received data queue, has key (Q QL) journal entry * to common data queue journal entry data structure. *==================================================================== P mapJrnE_Q_QL... P B D PI D i_pData * const D i_length 10I 0 const * * Local fields D tmpJrnEType_q_ql... D DS likeds(jrnEType_q_ql_t ) D jrnEType_q_ql... D DS likeds(jrnEType_q_ql_t ) D based(i_pData) D jrnEType_q... D DS likeds(jrnEType_q_t ) D based(i_pData) D key_q S 65535A based(pKey_q ) D key_ql S 65535A based(pKey_ql ) D tmpKey S 65535A based(pTmpKey ) * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
// Save journal data tmpJrnEType_q_ql = %subst(jrnEType_q_ql: 1: %len(tmpJrnEType_q_ql));
// Save key if (jrnEType_q_ql.keyLength > 0); pTmpKey = %alloc(tmpJrnEType_q_ql.keyLength); pKey_ql = %addr(jrnEType_q_ql) + %size(jrnEType_q_ql); %subst(tmpKey: 1: tmpJrnEType_q_ql.keyLength) = %subst(key_ql: 1: jrnEType_q_ql.keyLength); else; pTmpKey = *NULL; endif;
// Map journal data clear jrnEType_q;
jrnEType_q.sysInf_1 = tmpJrnEType_q_ql.sysInf_1; jrnEType_q.sysInf_2 = tmpJrnEType_q_ql.sysInf_2; jrnEType_q.sysInf_3 = *ALLx'00'; jrnEType_q.order = tmpJrnEType_q_ql.order; jrnEType_q.keyLength = tmpJrnEType_q_ql.keyLength; jrnEType_q.dataLength = 0; jrnEType_q.apiInf = *ALLx'00';
pKey_q = %addr(jrnEType_q) + %size(jrnEType_q); // key enforceBoundaries(i_pData: i_length: pKey_q: jrnEType_q.keyLength); %subst(key_q: 1: jrnEType_q.keyLength) = %subst(tmpKey: 1: tmpJrnEType_q_ql.keyLength);
// Free memory if (pTmpKey <> *NULL); dealloc(N) pTmpKey; endif;
/END-FREE P E * *==================================================================== * *** private *** * Map Data queue cleared, has key (Q QJ) journal entry * to common data queue journal entry data structure. *==================================================================== P mapJrnE_Q_QJ... P B D PI D i_pData * const D i_length 10I 0 const * * Local fields D tmpJrnEType_q_qj... D DS likeds(jrnEType_q_qj_t ) D jrnEType_q_qj... D DS likeds(jrnEType_q_qj_t ) D based(i_pData) D jrnEType_q... D DS likeds(jrnEType_q_t ) D based(i_pData) D key_q S 65535A based(pKey_q ) D key_qj S 65535A based(pKey_qj ) D tmpKey S 65535A based(pTmpKey ) * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
// Save journal data tmpJrnEType_q_qj = %subst(jrnEType_q_qj: 1: %len(tmpJrnEType_q_qj));
// Save key if (jrnEType_q_qj.keyLength > 0); pTmpKey = %alloc(tmpJrnEType_q_qj.keyLength); pKey_qj = %addr(jrnEType_q_qj) + %size(jrnEType_q_qj); %subst(tmpKey: 1: tmpJrnEType_q_qj.keyLength) = %subst(key_qj: 1: jrnEType_q_qj.keyLength); else; pTmpKey = *NULL; endif;
// Map journal data clear jrnEType_q;
jrnEType_q.sysInf_1 = *ALLx'00'; jrnEType_q.sysInf_2 = *ALLx'00'; jrnEType_q.sysInf_3 = *ALLx'00'; jrnEType_q.order = tmpJrnEType_q_qj.order; jrnEType_q.keyLength = tmpJrnEType_q_qj.keyLength; jrnEType_q.dataLength = 0; jrnEType_q.apiInf = *ALLx'00';
pKey_q = %addr(jrnEType_q) + %size(jrnEType_q); // key enforceBoundaries(i_pData: i_length: pKey_q: jrnEType_q.keyLength); %subst(key_q: 1: jrnEType_q.keyLength) = %subst(tmpKey: 1: tmpJrnEType_q_qj.keyLength);
// Free memory if (pTmpKey <> *NULL); dealloc(N) pTmpKey; endif;
/END-FREE P E * *==================================================================== * *** private *** * Ensures that memory boundaries are noticed. *==================================================================== P enforceBoundaries... P B D PI D i_pData * const D i_length 10I 0 const D i_pValue * const D i_size 10I 0 const * * Local fields D msg DS likeds(msg_t ) inz * * Messages /COPY QEXPJRNE,USR0020 * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
if (i_pValue >= i_pData and i_pValue <= i_pData + i_length - i_size); return; endif;
clear USR0020; msg = f_newMsg('USR0020': USR0020: cMsg_Escape); Message_sendEscapeMsg(msg);
/END-FREE P E * *==================================================================== * *** private *** * Produces an initialized record for a given file. *==================================================================== P crtEntryDataInitialized... P B D PI 32766A D i_file 10A const D i_lib 10A const D i_lastJrnFld 10A const * * Return value D entryData S 32766A inz * * Local fields D x S 10I 0 inz D isEntryDataFld S N inz(cFalse) D offset S 10I 0 inz D length S 10I 0 inz * * Cache for better performance D cache DS qualified static D isDirty N inz(cTrue) D file inz like(i_file ) D lib inz like(i_lib ) D data inz like(entryData) * * Field dictionary, needed to get additional * information for date fields D hFldDct S like(fldDct_handle_t) inz(*NULL) D flda0310 DS likeds(flda0310_t ) inz D flda0310s S like(flda0310_t ) D based(pFlda0310s) D pFlda0310s S * inz(%addr(flda0310 )) D msg DS likeds(msg_t ) inz * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
if (i_file <> cache.file) or (i_lib <> cache.lib); reset cache; endif;
if not cache.isDirty; return cache.data; endif;
// create field dictionary if not f_fldDct_new(i_file : i_lib : cFLDDCT_RCDFMT_FIRST : hFldDct : msg); f_sndPgmMsg(msg: cMsg_Prv: cMsg_ToPgmBdy); return ''; endif;
// spin through record format and initialize entry data isEntryDataFld = cFalse; offset = 0;
for x = 1 to f_FldDct_getNumE(hFldDct);
if x = 1; f_FldDct_rtvFldAtr(hFldDct: cFLDDCT_FLD_FIRST: flda0310s: 'FLDA0310'); else; f_FldDct_rtvFldAtr(hFldDct: cFLDDCT_FLD_NEXT: flda0310s: 'FLDA0310'); endif;
if flda0310.name = i_lastJrnFld; isEntryDataFld = cTrue; iter; endif;
if not isEntryDataFld; iter; endif;
// Initialize length of VAR-LENGTH fields if flda0310.varLength = '1'; length = flda0310.buffLength - flda0310.length; %subst(entryData: 1 + offset: length) = *ALLx'00'; offset = offset + length; else; length = 0; endif;
p_assert((flda0310.varLength = '1' and flda0310.buffLength <> flda0310.length) or (flda0310.varLength = '0' and flda0310.buffLength = flda0310.length) : 'Unexpected relation between ''flda0310.varLength'', + ''flda0310.length'' and ''flda0310.buffLength''');
// Initialize field for ... select; // ... binary data when flda0310.type = cFLDDCT_TYPE_BINARY; %subst(entryData: 1 + offset: flda0310.length) = *ALLx'00'; // ... float data when flda0310.type = cFLDDCT_TYPE_FLOAT; %subst(entryData: 1 + offset: flda0310.length) = *ALLx'00'; // ... zoned data when flda0310.type = cFLDDCT_TYPE_ZONED; %subst(entryData: 1 + offset: flda0310.length) = *ALLx'F0'; // ... packed data when flda0310.type = cFLDDCT_TYPE_PACKED; %subst(entryData: 1 + offset: flda0310.length) = *ALLx'00'; %subst(entryData: 1 + offset + flda0310.length - 1: 1) = x'0F'; // ... character data when flda0310.type = cFLDDCT_TYPE_CHAR; %subst(entryData: 1 + offset: flda0310.length) = *ALLx'40'; // ... graphic data when flda0310.type = cFLDDCT_TYPE_GRAPHIC; %subst(entryData: 1 + offset: flda0310.length) = *ALLx'00'; // ... date data when flda0310.type = cFLDDCT_TYPE_DATE; %subst(entryData: 1 + offset: flda0310.length) = '0001-01-01'; // ... time data when flda0310.type = cFLDDCT_TYPE_TIME; %subst(entryData: 1 + offset: flda0310.length) = '00.00.00'; // ... timestamp data when flda0310.type = cFLDDCT_TYPE_TMSTMP; %subst(entryData: 1 + offset: flda0310.length) = '0001-01-01-00.00.00.000000'; // ... large object (CLOB/BLOB) when flda0310.type = cFLDDCT_TYPE_LOB; %subst(entryData: 1 + offset: flda0310.buffLength) = '*POINTER';
other; msg = f_newMsg('USR0017': flda0310.name: cMsg_Diag); f_sndPgmMsg(msg: cMsg_Prv: cMsg_ToPgmBdy); msg = f_newMsg('USR0016': flda0310.name: cMsg_Escape); Message_sendEscapeMsg(msg); endsl;
offset = offset + flda0310.buffLength - length; endfor;
// delete field dictionary if hFldDct <> *NULL; f_fldDct_delete(hFldDct); endif;
// cache data cache.isDirty = cFalse; cache.file = i_file; cache.lib = i_lib; cache.data = entryData;
return entryData;
/END-FREE P E * *==================================================================== * *** private *** * Convert large object (CLOB/BLOB) field data. *==================================================================== P cvtLargeObjectFieldData... P B D PI D i_file 10A const D i_lib 10A const D i_lastJrnFld 10A const D io_data 32766A * * Local fields D x S 10I 0 inz D isEntryDataFld S N inz(cFalse) D offset S 10I 0 inz D length S 10I 0 inz * * Cache for better performance D cache DS qualified static D isDirty N inz(cTrue) D hasLobField N inz(cFalse) D file inz like(i_file ) D lib inz like(i_lib ) * * Field dictionary, needed to get additional * information for date fields D hFldDct S like(fldDct_handle_t) inz(*NULL) D flda0310 DS likeds(flda0310_t ) inz D flda0310s S like(flda0310_t ) D based(pFlda0310s) D pFlda0310s S * inz(%addr(flda0310 )) D msg DS likeds(msg_t ) inz * D LOB_DATA C x'00000000000000000000000000000000+ D 5CD7D6C9D5E3C5D94040404040404040' * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
if (i_file <> cache.file) or (i_lib <> cache.lib); reset cache; endif;
if (not cache.isDirty and not cache.hasLobField); return; endif;
// create field dictionary if not f_fldDct_new(i_file : i_lib : cFLDDCT_RCDFMT_FIRST : hFldDct : msg); f_sndPgmMsg(msg: cMsg_Prv: cMsg_ToPgmBdy); return; endif;
// spin through record format and initialize entry data isEntryDataFld = cFalse; offset = 0;
for x = 1 to f_FldDct_getNumE(hFldDct);
if x = 1; f_FldDct_rtvFldAtr(hFldDct: cFLDDCT_FLD_FIRST: flda0310s: 'FLDA0310'); else; f_FldDct_rtvFldAtr(hFldDct: cFLDDCT_FLD_NEXT: flda0310s: 'FLDA0310'); endif;
if flda0310.name = i_lastJrnFld; isEntryDataFld = cTrue; offset = offset + flda0310.buffLength - length; iter; endif;
if not isEntryDataFld; offset = offset + flda0310.buffLength - length; iter; endif;
if (flda0310.type = cFLDDCT_TYPE_CHAR and flda0310.buffLength = 32); if (%subst(io_data: 1 + offset: flda0310.buffLength) = LOB_DATA); %subst(io_data: 1 + offset: flda0310.buffLength) = '*POINTER'; cache.hasLobField = cTrue; endif; endif;
offset = offset + flda0310.buffLength - length; endfor;
// delete field dictionary if hFldDct <> *NULL; f_fldDct_delete(hFldDct); endif;
// cache data cache.isDirty = cFalse; cache.file = i_file; cache.lib = i_lib;
/END-FREE P E * *==================================================================== * *** private *** * Converts a DTS timestamp to an ISO timestamp. *==================================================================== P cvtDtsToIso... P B D PI Z D i_dtsTmStmp 20U 0 value * * Return value D timestamp S Z inz * * Local fields D tmpInBuffer S 8A based(pTmpInBuffer) D pTmpInBuffer S * inz D tmpBuffer DS D date 8A D time 9A D mSec 3A D errCode DS likeds(errCode_t ) * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
pTmpInBuffer = %addr(i_dtsTmStmp);
errCode = f_newApiErrCode(cTrue); QWCCVTDT('*DTS': tmpInBuffer: '*YYMD': tmpBuffer: errCode); mSec = *ALL'0';
timestamp = %timestamp(tmpBuffer: *ISO0);
return timestamp;
/END-FREE P E * *==================================================================== * *** private *** * Returns TRUE for a batch job, else FALSE. *==================================================================== P isBatchJob... P B D PI N * * Return value D isBatchJob S N inz(cFalse) * * Local fields D qJob DS likeds(qJob_t ) inz D jobi0100 DS likeds(jobi0100_t) inz D errCode DS likeds(errCode_t ) inz * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
qJob.name = '*'; qJob.user = ''; qJob.nbr = ''; errCode = f_newApiErrCode(cTrue);
QUSRJOBI(jobi0100: %size(jobi0100): 'JOBI0100': qJob: '': errCode);
if (f_isApiError(errCode)); isBatchJob = cTrue; else; if (jobi0100.type = 'I'); isBatchJob = cFalse; else; isBatchJob = cTrue; endif; endif;
return isBatchJob;
/END-FREE P E * *=====================================================================* * *** private *** * Closes the output file *=====================================================================* P closeOutputFile... P B D PI * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
if (g_file.isOpen and Rclose(g_file.pRFile) = 0); g_file.isOpen = cFalse; g_file.name = ''; endif;
/END-FREE P E * *=====================================================================* * Abnormal end procedure: Delete temporary file *=====================================================================* P AbnEnd_terminateExport... P B D PI D i_pRtxToken * const * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
monitor; closeOutputFile(); on-error; endmon;
/END-FREE P E * /if not defined(*V5R3M0) // *========================================================================= * *** private *** * Returns the bit-wise ANDing of the arguments. *========================================================================= P bitAND... P B D PI 10U 0 D i_arg1 10U 0 value D i_arg2 10U 0 value * * Return value D result S 10U 0 * * Helper fields * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
ANDSTR(%addr(result): %addr(i_arg1): %addr(i_arg2): %len(result));
return result;
/END-FREE P E * /endif

/IF NOT DEFINED(EXPJRNE_PROTOTYPE) *=====================================================================* * * * Application . : EXPJRNE * * Object . . . : EXPJRNER4 * * Description . : Export Journal Entries - SQL * * Author . . . : Thomas Raddatz <thomas.raddatz@tools400.de> * * Date . . . . : 23.10.2001 * * * *=====================================================================* * * * This software is free software, you can redistribute it and/or * * modify it under the terms of the GNU General Public License (GPL) * * as published by the Free Software Foundation. * * * * See GNU General Public License for details. * * http://www.opensource.org * * http://www.opensource.org/licenses/gpl-license.html * * * *=====================================================================* * History: * * * * Date Name Comment * * ---------- ------------ --------------------------------------- * * 23.12.2002 Th.Raddatz Fixed problem that field names longer * * than 10 characeters were not supported. * * * * 10.11.2005 Th.Raddatz Added option to select between outfile * * types: *TYPE1 / *TYPE2. * * * * 22.12.2005 Th.Raddatz Replaced local procedures by procedures * * of service program BASICS1. * * Fixed bug that non *ISO dates and times * * caused the program to crash. These * * values are now converted to CHARACTER. * * Replaced external data structures by * * type definitions using LIKEDS. * * * * 07.02.2006 Th.Raddatz Added outfile type *TYPE3 to support * * files with null-capable fields. * * * * 10.04.2006 Th.Raddatz Fixed problem with file names that * * contain a dot (.). * * * * 11.10.2006 D. Storch Added support for Datatyp BIGINT * * * * 10.10.2007 Th.Raddatz Now renaming field name if the name * * contains invalid chracaters. * * '.' is changed to '_'. * * * * 31.03.2008 Th.Raddatz Changed input parameter and return value * * of f_xlate() from 10A to 512A VARYING to * * support long field names of SQL tables. * * * * 18.09.2008 Th.Raddatz Fixed typo in #MSG_ENG when removing and * * adding message description USR0019 * * (wrong message file name). * * Renamed #MSG_ENG and #MSG_GER to * * A_MSG_ENG and A_MSG_GER. * * * * 19.09.2008 Th.Raddatz Changed size of sqlStr_t from 32767 to * * 65535 and added new typedef sqlStrV_t. * * Now retrieving description of output * * file from message description TXT0001. * * Fixed incorrect logical 'or' in * * f_cliProcessStmt(). SQL_SUCCESS and * * SQL_SUCCESS_WITH_INFO had to be ANDed. * * * * 20.09.2008 Th.Raddatz Redesigned EXPJRNE to support additional * * object types, starting with *DTAARA. * * * * 12.08.2009 Th.Raddatz Removed ' FOR SBCS DATA' clause. * * Added ' CCSID xxxxx' clause. * * * * 19.08.2009 Th.Raddatz Fixed problem that CCSID clause was * * incorrectly added to DATE, TIME and * * TIMESTAMP fields. * * * * 12.09.2009 Th.Raddatz Fixed problem that the CREATE TABLE * * statement ended in error if SQL reserved * * words (such as CHECK) were used as field * * names. * * * * 06.10.2014 Th.Raddatz Fixed compiler error RNF0203. * * * * 03.02.2015 Th.Raddatz Changed to generate a pseudo field * * for CLOB/BLOB fields. * * * * 22.09.2023 Th.Raddatz Changed generator to support TIMESTAMP * * fields with any number of fractional * * seconds. * * * *=====================================================================* * >>PRE-COMPILER<< * * >>CRTCMD<< CRTRPGMOD MODULE(&LI/&OB) + * * SRCFILE(&SL/&SF) + * * SRCMBR(&SM); * * >>IMPORTANT<< * * >>PARM<< TRUNCNBR(*NO); * * >>PARM<< DBGVIEW(*LIST); * * >>PARM<< OPTION(*EVENTF); * * >>PARM<< TGTRLS(V7R2M0); * * >>END-IMPORTANT<< * * >>EXECUTE<< * * >>END-PRE-COMPILER<< * *=====================================================================* H NOMAIN /COPY QEXPJRNE,H_SPEC *=====================================================================* /ENDIF * D f_crtOutfile_SQL... D PR N D extproc('EXPJRNER4_+ D f_crtOutfile_SQL+ D ') D i_tplFile 10A const D i_tplLib 10A const D i_outFile 10A const D i_outLib 10A const D i_outFilFmt 10A const * /IF DEFINED(EXPJRNE_PROTOTYPE) /EOF /ENDIF * /COPY QBASICS1,PBASICS1 Tools/400 Runtime Library /COPY QEXPJRNE,CEELIB CEE APIs /COPY QEXPJRNE,SQL Embedded SQL type definitions and const. * /DEFINE EXPJRNE_PROTOTYPE /COPY QEXPJRNE,EXPJRNER6 Tool: EXPJRNE SQL Call Level Interface /COPY QEXPJRNE,EXPJRNER7 Tool: EXPJRNE Utilities /UNDEFINE EXPJRNE_PROTOTYPE * * Typedefs D sqlStrV_t S 65535A varying based(pDummy) * * Constants * ... double quotes D cDOUBLE_QUOTE C const('"') D cSINGLE_QUOTE C const('''') * * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - * Internal prototypes * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - * D p_abnEndProc... D PR extproc('p_abnEndProc') D i_pRtxToken * const * D RtxToken_t DS qualified based(pDummy) D hList like(BasicList_handle_t ) D hSqlCli likeds(hSqlCli_t ) * *=====================================================================* * Create outfile *=====================================================================* * P f_crtOutfile_SQL... P B export D PI N D i_tplFile 10A const D i_tplLib 10A const D i_outFile 10A const D i_outLib 10A const D i_outFilFmt 10A const * * return value D isOK S N inz(cFalse) * * fields D x S 10I 0 inz D tplFile DS likeds(qObj_t ) inz D fldAttr DS likeds(fldAttr_t ) based(pFldAttr) D rc S like(SQLRETCODE_t) inz D ts_fraction S 10I 0 inz * D sqlStrFld S like(sqlStrV_t ) inz D sqlStrText S like(sqlStrV_t ) inz D sqlStrCHdg S like(sqlStrV_t ) inz D sqlStrDesc S like(sqlStrV_t ) inz D text S 52A inz D msg DS likeds(msg_t) * D rtxToken DS likeds(rtxToken_t) inz * * Messages /COPY QEXPJRNE,USR0024 /COPY QEXPJRNE,USR0025 /COPY QEXPJRNE,USR0026 /COPY QEXPJRNE,USR0027 * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
rtxToken.hSqlCli = SQLCLI_null(); rtxToken.hList = BasicList_null();
// Register abnormal end procedure CEERTX(%paddr('p_abnEndProc'): %addr(rtxToken): *omit);
dou '1';
// Connect to DB Server Message_sendStatusMsg('USR0001'); SQLCLI_initialize(rtxToken.hSqlCli);
// Retrieve Outfile Record Format Message_sendStatusMsg('USR0002');
// Produce field list ... rtxToken.hList = BasicList_new('*COLUMNS': 256);
tplFile.name = i_tplFile; tplFile.lib = i_tplLib; getOutputFileColumns(rtxToken.hList: i_outFilFmt: tplFile);
// Initialize SQL statements sqlStrFld = 'CREATE TABLE ' + %trim(i_outLib) + '.' + cDOUBLE_QUOTE + %trim(i_outFile) + cDOUBLE_QUOTE + ' (';
sqlStrText = 'LABEL ON ' + %trim(i_outLib) + '.' + cDOUBLE_QUOTE + %trim(i_outFile) + cDOUBLE_QUOTE + ' (';
sqlStrCHdg = 'LABEL ON ' + %trim(i_outLib) + '.' + cDOUBLE_QUOTE + %trim(i_outFile) + cDOUBLE_QUOTE + ' (';
// Loop through column list and create SQL statements for x = 1 to BasicList_getNumE(rtxToken.hList); pFldAttr = BasicList_get(rtxToken.hList: x);
// -------------------------------------------------- // produce SQL command: CREATE TABLE // --------------------------------------------------
// ... column name sqlStrFld = sqlStrFld + f_addQuotes(fldAttr.flda0320.alias : cDOUBLE_QUOTE);
// ... add data type select; when (fldAttr.sqlType = cSQL_TYPE_CHARACTER ) or (fldAttr.sqlType = cSQL_TYPE_VARCHAR );
sqlStrFld = sqlStrFld + ' ' + fldAttr.sqlType + ' (' + %trim(%editc(fldAttr.flda0320.length: 'Z')) + ')';
when (fldAttr.sqlType = cSQL_TYPE_SMALLINT ) or (fldAttr.sqlType = cSQL_TYPE_INTEGER ) or (fldAttr.sqlType = cSQL_TYPE_BIGINT ) or (fldAttr.sqlType = cSQL_TYPE_DOUBLE ) or (fldAttr.sqlType = cSQL_TYPE_FLOAT ) or (fldAttr.sqlType = cSQL_TYPE_REAL ) or (fldAttr.sqlType = cSQL_TYPE_DATE ) or (fldAttr.sqlType = cSQL_TYPE_TIME );
sqlStrFld = sqlStrFld + ' ' + fldAttr.sqlType;
when (fldAttr.sqlType = cSQL_TYPE_TIMESTAMP );
if (fldAttr.flda0320.length = 19); ts_fraction = 0; else; ts_fraction = fldAttr.flda0320.length - 20; endif;
sqlStrFld = sqlStrFld + ' ' + fldAttr.sqlType + ' (' + %char(ts_fraction) + ')';
when (fldAttr.sqlType = cSQL_TYPE_GRAPHIC ) or (fldAttr.sqlType = cSQL_TYPE_VARGRAPHIC);
sqlStrFld = sqlStrFld + ' ' + fldAttr.sqlType + ' (' + %trim(%editc(fldAttr.flda0320.digits: 'Z')) + ')';
when (fldAttr.sqlType = cSQL_TYPE_DECIMAL ) or (fldAttr.sqlType = cSQL_TYPE_NUMERIC );
sqlStrFld = sqlStrFld + ' ' + fldAttr.sqltype + ' (' + %trim(%editc(fldAttr.flda0320.digits: 'Z')) + ', ' + %char(fldAttr.flda0320.decPos) + ')';
when (fldAttr.sqlType = cSQL_TYPE_BLOB ) or (fldAttr.sqlType = cSQL_TYPE_CLOB );
sqlStrFld = sqlStrFld + ' ' + cSQL_TYPE_CHARACTER + ' (' + %trim(%editc(fldAttr.flda0320.buffLength: 'Z')) + ')';
endsl;
// ... CCSID // if (fldAttr.sqlType = cSQL_TYPE_CHARACTER or // fldAttr.sqlType = cSQL_TYPE_VARCHAR ); // sqlStrFld = sqlStrFld + ' FOR SBCS DATA'; // endif; if (hasCcsidClause(fldAttr.flda0320.type : fldAttr.flda0320.ccsid)); sqlStrFld = sqlStrFld + ' CCSID ' + %char(fldAttr.flda0320.ccsid); endif;
// ... NULL capability if (fldAttr.flda0320.alwNull = cFalse); sqlStrFld = sqlStrFld + ' NOT NULL WITH DEFAULT'; endif;
// -------------------------------------------------- // produce SQL command: ALTER TABLE (text) // -------------------------------------------------- sqlStrText = sqlStrText + f_addQuotes(fldAttr.flda0320.alias: cDOUBLE_QUOTE) + ' TEXT IS ' + cSINGLE_QUOTE + f_replace(cSINGLE_QUOTE: cSINGLE_QUOTE + cSINGLE_QUOTE: %trim(fldAttr.flda0320.text)) + cSINGLE_QUOTE;
// -------------------------------------------------- // produce SQL command: ALTER TABLE (column heading) // -------------------------------------------------- sqlStrCHdg = sqlStrCHdg + f_addQuotes(fldAttr.flda0320.alias: cDOUBLE_QUOTE) + ' IS ' + cSINGLE_QUOTE + f_replace(cSINGLE_QUOTE: cSINGLE_QUOTE + cSINGLE_QUOTE: fldAttr.flda0320.colHdg1 + fldAttr.flda0320.colHdg2 + fldAttr.flda0320.colHdg3) + cSINGLE_QUOTE;
if (x <> BasicList_getNumE(rtxToken.hList)); sqlStrFld = sqlStrFld + ', '; sqlStrText = sqlStrText + ', '; sqlStrCHdg = sqlStrCHdg + ', '; endif; endfor;
// Finish SQL statements sqlStrFld = sqlStrFld + ')'; sqlStrText = sqlStrText+ ')'; sqlStrCHdg = sqlStrCHdg+ ')';
// Create Outfile Message_sendStatusMsg('USR0003');
dou '1'; rc = SQLCLI_executeDirect(rtxToken.hSqlCli: sqlStrFld); if (rc = SQL_ERROR); clear USR0024; USR00241 = sqlStrFld; Message_sendDiagMsg(f_newMsg('USR0024': USR0024)); leave; endif;
rc = SQLCLI_executeDirect(rtxToken.hSqlCli: sqlStrText); if (rc = SQL_ERROR); clear USR0025; USR00251 = sqlStrText; Message_sendDiagMsg(f_newMsg('USR0025': USR0025)); leave; endif;
rc = SQLCLI_executeDirect(rtxToken.hSqlCli: sqlStrCHdg); if (rc = SQL_ERROR); clear USR0026; USR00261 = sqlStrCHdg; Message_sendDiagMsg(f_newMsg('USR0026': USR0026)); leave; endif;
msg = f_newMsg('TXT0001'); text = f_rtvMsgText(msg); text = f_addQuotes(%trimR(text): cSINGLE_QUOTE);
sqlStrDesc = 'LABEL ON TABLE ' + %trim(i_outLib) + '.' + %trim(i_outFile) + ' IS ' + text;
rc = SQLCLI_executeDirect(rtxToken.hSqlCli: sqlStrDesc); if (rc = SQL_ERROR); clear USR0027; USR00271 = sqlStrDesc; Message_sendDiagMsg(f_newMsg('USR0027': USR0027)); leave; endif; enddo;
if (rc = SQL_ERROR); Message_sendDiagMsg(SQLCLI_Error_get()); endif;
// Disconnect from DB Server SQLCLI_terminate(rtxToken.hSqlCli);
// Unregister abnormal end procedure CEEUTX(%paddr('p_abnEndProc'): *omit);
isOK = cTrue; enddo;
// Delete temporary objects Message_sendStatusMsg('USR0004');
// House keeping // ... list of columns if (not BasicList_isNull(rtxToken.hList)); BasicList_delete(rtxToken.hList); rtxToken.hList = BasicList_null(); endif; // ... SQL call level interface if (not SQLCLI_isNull(rtxToken.hSqlCli)); SQLCLI_terminate(rtxToken.hSqlCli); rtxToken.hSqlCli = SQLCLI_null(); endif;
return isOK;
/END-FREE P E * *=====================================================================* * Terminate SQL connection *=====================================================================* * P p_abnEndProc... P B D PI D i_pRtxToken * const * D rtxToken DS likeds(rtxToken_t) based(i_pRtxToken) * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
if (not BasicList_isNull(rtxToken.hList)); BasicList_delete(rtxToken.hList); rtxToken.hList = BasicList_null(); endif;
SQLCLI_shutdown(); rtxToken.hSqlCli = SQLCLI_null();
/END-FREE P E *

      /IF NOT DEFINED(EXPJRNE_PROTOTYPE)
