s the date format of the job. D rtvJobDateFmt... D PR 10A varying D extproc('EXPJRNER7_+ D rtvJobDateFmt+ D ') * * Retrieve Journal Information D rtvJrnInf... D PR N D extproc('EXPJRNER7_+ D rtvJrnInf+ D ') D i_obj 10A const D i_lib 10A const D i_objType 10A const D o_file 10A D o_lib 10A D o_active N D o_jrn 10A D o_jrnLib 10A D o_images 10A D o_omtJrnE 10A * * Converts a given SQL raw data type (integer value) to * its external character representation. D sqlTypeToString... D PR 32A varying D extproc('EXPJRNER7_+ D sqlTypeToString+ D ') D i_sqltype 10I 0 const * * Converts a given RPG data type to its SQL representation. D rpgTypeToSqlString... D PR 32A varying D extproc('EXPJRNER7_+ D rpgTypeToSqlString+ D ') D i_rpgType 1A const D i_length 10I 0 const options(*nopass) * * Converts invalid characters. D xlate... D PR 512A varying D extproc('EXPJRNER7_+ D xlate+ D ') D i_string 512A const varying * * Returns the list of columns of the output file. D getOutputFileColumns... D PR D extproc('EXPJRNER7_+ D getOutputFileColumns+ D ') D i_hList const like(BasicList_handle_t ) D i_outFilFmt 10A const D i_tplFile const likeds(qObj_t ) * * Returns cTrue if the field has a CCSID clause. D hasCcsidClause... D PR N D extproc('EXPJRNER7_+ D hasCcsidClause+ D ') D i_type 1A const D i_ccsid 10U 0 const * * Sets the name of the output file. D OutputFile_setName... D PR D extproc('EXPJRNER7_+ D OutputFile_setName+ D ') D i_file 10A const * * Returns the name of the output file. D OutputFile_getName... D PR 10A D extproc('EXPJRNER7_+ D OutputFile_getName+ D ') * * Sets the name of the library that contains the output file. D OutputFile_setLibrary... D PR D extproc('EXPJRNER7_+ D OutputFile_setLibrary+ D ') D i_file 10A const * * Returns the name of the library that contains the output file. D OutputFile_getLibrary... D PR 10A D extproc('EXPJRNER7_+ D OutputFile_getLibrary+ D ') * * Sets the name of the member of the output file that is used to * receive the exported journal entries. D OutputFile_setMember... D PR D extproc('EXPJRNER7_+ D OutputFile_setMember+ D ') D i_file 10A const * * Returns the name of the member of the output file that is used to * receive the exported journal entries. D OutputFile_getMember... D PR 10A D extproc('EXPJRNER7_+ D OutputFile_getMember+ D ') * * Sets the type of the output format. D OutputFile_setOutputFileFormat... D PR D extproc('EXPJRNER7_+ D OutputFile_setOutputFileFormat+ D ') D i_outFilFmt 10A const * * Returns the type of the output format. D OutputFile_getOutputFileFormat... D PR 10A D extproc('EXPJRNER7_+ D OutputFile_getOutputFileFormat+ D ') * * Sets the name of the template file. D TemplateFile_setName... D PR D extproc('EXPJRNER7_+ D TemplateFile_setName+ D ') D i_file 10A const * * Returns the name of the template file. D TemplateFile_getName... D PR 10A D extproc('EXPJRNER7_+ D TemplateFile_getName+ D ') * * Sets the name of the library that contains the template file. D TemplateFile_setLibrary... D PR D extproc('EXPJRNER7_+ D TemplateFile_setLibrary+ D ') D i_lib 10A const * * Returns the name of the library that contains the template file. D TemplateFile_getLibrary... D PR 10A D extproc('EXPJRNER7_+ D TemplateFile_getLibrary+ D ') * * Returns cTrue if the output file format does not matches the required format. D OutputFile_isLevelCheck... D PR N D extproc('EXPJRNER7_+ D OutputFile_isLevelCheck+ D ') D o_msg likeds(msg_t ) D options(*nopass) * * Sets the name of object whose journal entries are exported. D Object_setName... D PR D extproc('EXPJRNER7_+ D Object_setName+ D ') D i_obj 10A const * * Returns the name of object whose journal entries are exported. D Object_getName... D PR 10A D extproc('EXPJRNER7_+ D Object_getName+ D ') * * Sets the name of the library that contains * the object whose journal entries are exported. D Object_setLibrary... D PR D extproc('EXPJRNER7_+ D Object_setLibrary+ D ') D i_file 10A const * * Rteurns the name of the library that contains * the object whose journal entries are exported. D Object_getLibrary... D PR 10A D extproc('EXPJRNER7_+ D Object_getLibrary+ D ') * * Sets the type of the object whose journal entries are exported. D Object_setType... D PR D extproc('EXPJRNER7_+ D Object_setType+ D ') D i_file 10A const * * Returns the type of the object whose journal entries are exported. D Object_getType... D PR 10A D extproc('EXPJRNER7_+ D Object_getType+ D ') * * Resets the error counter. D Error_resetCounter... D PR D extproc('EXPJRNER7_+ D Error_resetCounter+ D ') * * Increments the error counter by one. D Error_incrementCounter... D PR D extproc('EXPJRNER7_+ D Error_incrementCounter+ D ') * * Returns the number of errors. D Error_getCounterAsString... D PR 10A D extproc('EXPJRNER7_+ D Error_getCounterAsString+ D ') * * Sends a status message. D Message_sendStatusMsg... D PR D extproc('EXPJRNER7_+ D Message_sendStatusMsg+ D ') D i_ID const like(msg_t.ID ) D i_data const like(msg_t.data ) D options(*nopass) * * Sends a diagnostic message. D Message_sendDiagMsg... D PR D extproc('EXPJRNER7_+ D Message_sendDiagMsg+ D ') D i_msg value likeds(msg_t ) * * Sends an escape message. D Message_sendEscapeMsg... D PR D extproc('EXPJRNER7_+ D Message_sendEscapeMsg+ D ') D i_msg value likeds(msg_t ) * * Returns the current release level of the operating system. D System_getCurrentRelease... D PR 6A D extproc('EXPJRNER7_+ D System_getCurrentRelease+ D ') * * Returns the application library of the EXPJRNE utility. D Application_getLibrary... D PR 10A D extproc('EXPJRNER7_+ D Application_getLibrary+ D ') * /IF DEFINED(EXPJRNE_PROTOTYPE) /EOF /ENDIF * /COPY QBASICS1,PBASICS1 Tools/400 Runtime Library /COPY QEXPJRNE,QUSRJOBI Retrieve Job Information (QUSRJOBI) API /COPY QEXPJRNE,FDQJOB typedef: Qualified Job Name /COPY QEXPJRNE,FDOBJD0400 typedef: QUSROBJD API - OBJD0400 /COPY QEXPJRNE,QUSROBJD Retrieve Object Description (QUSROBJD) API /COPY QEXPJRNE,SQLCLI SQL-Call Level Interface /COPY QEXPJRNE,SQL Embedded SQL type definitions and const. /COPY QEXPJRNE,QWCRDTAA Retrieve Data Area (QWCRDTAA) API /COPY QEXPJRNE,QMHQRDQD Retrieve Data Queue Description (QMHQRDQD) /COPY QEXPJRNE,JRNETYPES Layouts for var.-length portion of jrnE /COPY QEXPJRNE,CEELIB CEE APIs * /DEFINE EXPJRNE_PROTOTYPE /COPY QEXPJRNE,EXPJRNER6 EXPJRNE: SQL type definitions and const. /UNDEFINE EXPJRNE_PROTOTYPE * * Adds the columns of a given file to a given column list. D addColumns... D PR like(SQLRETCODE_t ) D extproc('EXPJRNER7_+ D addColumns+ D ') D i_hList const like(BasicList_handle_t ) D i_file const likeds(qObj_t ) D i_lastField 10A const options(*nopass) * * Adds variable-length portion of journal entries of type *DTAARA. D addDataAreaVarLenFields... D PR like(SQLRETCODE_t ) D extproc('EXPJRNER7_+ D addDataAreaVarLenFields+ D ') D i_hList const like(BasicList_handle_t ) * * Adds variable-length portion of journal entries of type *DTAQ. D addDataQueueVarLenFields... D PR like(SQLRETCODE_t ) D extproc('EXPJRNER7_+ D addDataQueueVarLenFields+ D ') D i_hList const like(BasicList_handle_t ) * * Produces a field attribute structure. D produceFldAttr... D PR likeds(fldAttr_t ) D extproc('EXPJRNER7_+ D produceFldAttr+ D ') D i_name 10A const D i_type 1A const D i_length 10I 0 const D i_decPos 10I 0 const options(*omit) D i_text 50A const D i_colHdg 60A const * * Returns the data type of a given data area. D getDataAreaType... D PR likeds(fldAttr_t ) D extproc('EXPJRNER7_+ D getDataAreaType+ D ') D i_dtaAra 10A const D i_lib 10A const * * Returns the data type of a given data queue. D getDataQueueType... D PR likeds(fldAttr_t ) D extproc('EXPJRNER7_+ D getDataQueueType+ D ') D i_dtaAra 10A const D i_lib 10A const * * Returns the key type of a given keyed data queue. D getDataQueueKey... D PR likeds(fldAttr_t ) D extproc('EXPJRNER7_+ D getDataQueueKey+ D ') D i_dtaAra 10A const D i_lib 10A const * /DEFINE SDS_EXTENDED /COPY QEXPJRNE,SDS * * Current program state D g_state DS qualified inz D qObj likeds(qObj_t ) D objType 10A D qOutFile likeds(qObj_t ) D outMbr 10A D outFilFmt 10A D qTplFile likeds(qObj_t ) D errCount 10I 0 * * Constants * ... TYPE1 outfile D cType1File C const('QADSPJRN') D cType1Lib C const('QTEMP' ) * * ... TYPE2 outfile D cType2File C const('QADSPJR2') D cType2Lib C const('QTEMP' ) * * ... TYPE3 outfile D cType3File C const('QADSPJR3') D cType3Lib C const('QTEMP' ) * * ... TYPE4 outfile D cType4File C const('QADSPJR4') D cType4Lib C const('QTEMP' ) * * ... TYPE5 outfile D cType5File C const('QADSPJR5') D cType5Lib C const('QTEMP' ) * *==================================================================* * Returns the date format of the job. *==================================================================* P rtvJobDateFmt... P B export D PI 10A varying * * Return value D dateFmt S 10A varying inz * * Local fields D qJob DS likeds(qJob_t ) inz D jobi0400 DS likeds(jobi0400_t ) inz * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
qJob.name = '*'; qJob.user = ''; qJob.nbr = '';
QUSRJOBI(JOBI0400: %size(JOBI0400): 'JOBI0400': qJob: '');
dateFmt = jobi0400.dateFmt;
return dateFmt;
/END-FREE P E * *==================================================================== * Retrieve Journal Information *==================================================================== * Input : i_file - The name of the file about which the * information is to be retrieved from. * i_lib - The library of the file. * Special values: *LIBL, *CURLIB * * Output: o_file - The actual file name from which the * information was retrieved from. * o_lib - The actual library of the file. * o_active - Journaling active. * TRUE = File is beeing journaled. * FALSE = File is not beeing journaled. * o_jrn - The name of the journal. * o_jrnLib - The library of the journal. * o_images - Record images that are journaled. * *BOTH = Both images are written * to the journal. * *AFTER = Only after images are written * to the journal. * o_omtJrnE - Journal entries that are omitted. * *NONE = No journal entries are omitted. * *OPNCLO = Open and close entries are omitted. * *==================================================================== P rtvJrnInf... P B export D PI N D i_obj 10A const D i_lib 10A const D i_objType 10A const D o_obj 10A D o_lib 10A D o_active N D o_jrn 10A D o_jrnLib 10A D o_images 10A D o_omtJrnE 10A * * return value D isOK S N inz(cFalse) * * work fields D qObj DS likeds(qObj_t ) inz D objd0400 DS likeds(objd0400_t ) inz D errCode DS likeds(errCode_t ) inz * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
// Determine initial size of memory needed ... qObj.name = i_obj; qObj.lib = i_lib; errCode = f_newApiErrCode(cTrue);
QUSROBJD(objd0400: %size(objd0400): 'OBJD0400' : qObj: i_objType: errCode);
// Is there was an error, ... if (f_isApiError(errCode)); // ... then clear return values o_obj = ''; o_lib = ''; o_active = cFalse; o_jrn = ''; o_jrnLib = ''; o_images = ''; o_omtJrnE = ''; return cFalse; endif;
o_obj = objd0400.name; o_lib = objd0400.rtnLib;
if (objd0400.jrnStat = '1'); o_active = cTrue; o_jrn = objd0400.jrnName; o_jrnLib = objd0400.jrnLibName;
if (objd0400.jrnImages = '0'); o_images = '*AFTER'; else; o_images = '*BOTH'; endif;
if (objd0400.jrnOmitE = '0'); o_omtJrnE = '*NONE'; else; o_omtJrnE = '*OPNCLO'; endif;
else; o_active = cFalse; o_jrn = ''; o_jrnLib = ''; o_images = ''; o_omtJrnE = ''; endif;
return cTrue;
/END-FREE P E * *==================================================================== * Converts a given SQL raw data type (integer value) to * its external character representation. *==================================================================== * Input : i_sqlType - Internal SQL data type as returned by * SQLColAttributes(). * * Return: extType - Character representation of i_sqlType. *==================================================================== P sqlTypeToString... P B export D PI 32A varying D i_sqltype 10I 0 const * * return value D dataType S 10A varying inz('*N') * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
// Determine initial size of memory needed ... Select; When (i_sqltype = SQL_CHAR); dataType = cSQL_TYPE_CHARACTER; When (i_sqltype = SQL_VARCHAR); dataType = cSQL_TYPE_VARCHAR; When (i_sqltype = SQL_GRAPHIC); dataType = cSQL_TYPE_GRAPHIC; When (i_sqltype = SQL_VARGRAPHIC); dataType = cSQL_TYPE_VARGRAPHIC; When (i_sqltype = SQL_WCHAR); dataType = cSQL_TYPE_GRAPHIC; When (i_sqltype = SQL_WVARCHAR); dataType = cSQL_TYPE_VARGRAPHIC; When (i_sqltype = SQL_SMALLINT); dataType = cSQL_TYPE_SMALLINT; When (i_sqltype = SQL_INTEGER); dataType = cSQL_TYPE_INTEGER; When (i_sqltype = SQL_BIGINT); dataType = cSQL_TYPE_BIGINT; When (i_sqltype = SQL_DECIMAL); dataType = cSQL_TYPE_DECIMAL; When (i_sqltype = SQL_NUMERIC); dataType = cSQL_TYPE_NUMERIC; When (i_sqltype = SQL_DOUBLE); dataType = cSQL_TYPE_DOUBLE; When (i_sqltype = SQL_FLOAT); dataType = cSQL_TYPE_FLOAT; When (i_sqltype = SQL_REAL); dataType = cSQL_TYPE_REAL; When (i_sqltype = SQL_DATE); dataType = cSQL_TYPE_DATE; When (i_sqltype = SQL_TIME); dataType = cSQL_TYPE_TIME; When (i_sqltype = SQL_TIMESTAMP); dataType = cSQL_TYPE_TIMESTAMP; When (i_sqltype = SQL_BLOB); dataType = cSQL_TYPE_BLOB; When (i_sqltype = SQL_CLOB); dataType = cSQL_TYPE_CLOB; Other; dataType = '*INVALID_DATA_TYPE'; Endsl;
return dataType;
/END-FREE P E * *==================================================================== * Converts a given SQL raw data type (integer value) to * its external character representation. *==================================================================== * Input : i_sqlType - Internal SQL data type as returned by * SQLColAttributes(). * * Return: extType - Character representation of i_sqlType. *==================================================================== P rpgTypeToSqlString... P B export D PI 32A varying D i_rpgType 1A const D i_length 10I 0 const options(*nopass) * * Parameter positions D p_length C 2 * * Fields for optional parameters D length S like(i_length) inz * * return value D dataType S 10A varying inz('*N') * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
if (%parms() >= p_length); length = i_length; else; length = 0; endif;
// Determine initial size of memory needed ... select; when (i_rpgType = 'A'); dataType = sqlTypeToString(SQL_CHAR);
