/END-FREE P E * *==================================================================== * Returns the name of object whose journal entries are exported. *==================================================================== * Input : void * * Return: obj - Name of the object whose journal entries * are exported. *==================================================================== P Object_getName... P B export D PI 10A * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
return g_state.qObj.name;
/END-FREE P E * *==================================================================== * Returns the name of the library that contains * the object whose journal entries are exported. *==================================================================== * Input : void * * Return: lib - Name of the library that contains the object * whose journal entries are exported. *==================================================================== P Object_getLibrary... P B export D PI 10A * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
return g_state.qObj.lib;
/END-FREE P E * *==================================================================== * Returns the type of the object whose journal entries are exported. *==================================================================== * Input : void * * Return: type - Type of the object whose journal entries * are exported. *==================================================================== P Object_getType... P B export D PI 10A * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
return g_state.objType;
/END-FREE P E * *==================================================================== * Resets the error counter. *==================================================================== * Input : void * * Return: void *==================================================================== P Error_resetCounter... P B export D PI * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
g_state.errCount = 0;
/END-FREE P E * *==================================================================== * Increments the error counter by one. *==================================================================== * Input : void * * Return: void *==================================================================== P Error_incrementCounter... P B export D PI * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
g_state.errCount = g_state.errCount + 1;
/END-FREE P E * *==================================================================== * Returns the number of errors. *==================================================================== * Input : void * * Return: counter - Number of errors that occured. *==================================================================== P Error_getCounterAsString... P B export D PI 10A * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
return %char(g_state.errCount);
/END-FREE P E * *==================================================================== * Sends a status message. *==================================================================== * Input : i_id - Message ID. * i_data - Message data. * * Return: void *==================================================================== P Message_sendStatusMsg... P B export D PI D i_ID const like(msg_t.ID ) D i_data const like(msg_t.data ) D options(*nopass) * * Parameter positions D c_data C 2 * * Local fields D msg DS likeds(msg_t ) inz * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
if (%parms() >= c_data); msg = f_newMsg(i_ID: i_data: cMsg_Status); else; msg = f_newMsg(i_ID: '': cMsg_Status); endif;
f_sndPgmMsg(msg: cMsg_Ext);
/END-FREE P E * *==================================================================== * Sends a diagnostic message. *==================================================================== * Input : i_id - Message ID. * i_data - Message data. * * Return: void *==================================================================== P Message_sendDiagMsg... P B export D PI D i_msg value likeds(msg_t ) * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
i_msg.type = cMsg_Diag; f_sndPgmMsg(i_msg: cMsg_Prv: cMsg_ToCtlBdy);
/END-FREE P E * *==================================================================== * Sends an escape message. *==================================================================== * Input : i_id - Message ID. * i_data - Message data. * * Return: void *==================================================================== P Message_sendEscapeMsg... P B export D PI D i_msg value likeds(msg_t ) * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
i_msg.type = cMsg_Escape; f_sndPgmMsg(i_msg: cMsg_Prv: cMsg_ToCtlBdy);
/END-FREE P E * *==================================================================== * Returns the current release level of the operating system. *==================================================================== * Input : void * * Return: VxRxMx *==================================================================== P System_getCurrentRelease... P B export D PI 6A * * QSZRTVPR API D QSZRTVPR... D PR extpgm('QSZRTVPR') D o_rcvVar 65535A options(*varsize) D i_lenRcvVar 10I 0 const D i_format 8A const D o_prodInf 65535A const options(*varsize) D io_errCode 65535A options(*varsize) * D prdi0100 DS qualified D productID 1 7A inz('*OPSYS') D releaseLvl 8 13A inz('*CUR' ) D productOpt 14 17A inz('0000' ) D loadID 18 27A inz('*CODE' ) * Shortened!: D prdr0100 DS qualified D bytRet 1 4I 0 D bytAvl 5 8I 0 D reserved_1 9 12I 0 D productID 13 19A D releaseLvl 20 25A * * API error code D errCode DS likeds(errCode_t ) inz * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
errCode = f_newApiErrCode(cFalse);
QSZRTVPR(prdr0100: %size(prdr0100): 'PRDR0100': prdi0100: errCode);
return prdr0100.releaseLvl;
/END-FREE P E * *==================================================================== * Returns the name of the library that contains the output file. *==================================================================== * Input : void * * Return: library-name *==================================================================== P Application_getLibrary... P B export D PI 10A * - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - /FREE
return sds.pgmLib;
/END-FREE P E *

     /* =================================================================== */
     /*                                                                     */
     /*  Application . : EXPJRNE                                            */
     /*  Object  . . . : EXPJRNEV                                           */
     /*  Description . : EXPJRNE - Validity Checker Example                 */
     /*  Author  . . . : Thomas Raddatz   <thomas.raddatz@tools400.de>      */
     /*  Date  . . . . : 08.12.2014                                         */
     /*                                                                     */
     /* =================================================================== */
     /*  Purpose of the EXPJRNEV validity checker program:                  */
     /*                                                                     */
     /*     The EXPJRNEV demonstrates how to write a validity checker       */
     /*     program for the EXPJRNE command.                                */
     /*     This sample program checks the following conditions:            */
     /*      - File to receive output: must match *DFT                      */
     /*          Library             : must match QTEMP                     */
     /*      - Create outfile        : must match *NO                       */
     /*      - Journalthat are not allowed to export journal entries        */
     /*        from:   FOO/BAA                                              */
     /*                                                                     */
     /*  Compiling the validity checker:                                    */
     /*                                                                     */
     /*     CRTCLMOD MODULE(yourLib/EXPJRNEV) SRCFILE(yourLib/QEXPJRNE)     */
     /*       SRCMBR(*MODULE) DBGVIEW(*LIST)                                */
     /*                                                                     */
     /*     CRTPGM   PGM(yourLib/EXPJRNEV) MODULE(*PGM)                     */
     /*       ACTGRP(*CALLER) BNDSRVPGM(yourLib/EXPJRNECU)                  */
     /*                                                                     */
     /*  Activating the validity checker:                                   */
     /*                                                                     */
     /*     CHGCMD CMD(yourLib/EXPJRNE) VLDCKR(yourLib/EXPJRNEV)            */
     /*                                                                     */
     /*  Deactivating the validity checker:                                 */
     /*                                                                     */
     /*     CHGCMD CMD(yourLib/EXPJRNE) VLDCKR(*NONE)                       */
     /*                                                                     */
     /* =================================================================== */
     /*                                                                     */
     /*  This software is free software, you can redistribute it and/or     */
     /*  modify it under the terms of the GNU General Public License (GPL)  */
     /*  as published by the Free Software Foundation.                      */
     /*                                                                     */
     /*  See GNU General Public License for details.                        */
     /*          http://www.opensource.org                                  */
     /*          http://www.opensource.org/licenses/gpl-license.html        */
     /*                                                                     */
     /* =================================================================== */
     /*  History:                                                           */
     /*                                                                     */
     /*  Date        Name          Comment                                  */
     /*  ----------  ------------  ---------------------------------------  */
     /*                                                                     */
     /* =================================================================== */
     /* >>PRE-COMPILER<<                                                    */
     /*   >>CRTCMD<< CRTCLMOD     MODULE(&LI/&OB) +                         */
     /*                           SRCFILE(&SL/&SF) +                        */
     /*                           SRCMBR(*MODULE);                          */
     /*   >>IMPORTANT<<                                                     */
     /*     >>PARM<< DBGVIEW(*LIST);                                        */
     /*     >>PARM<< OPTION(*EVENTF);                                       */
     /*     >>PARM<< TGTRLS(V7R2M0);                                        */
     /*   >>END-IMPORTANT<<                                                 */
     /*   >>EXECUTE<<                                                       */
     /*   >>CMD<<    CRTPGM       PGM(&LI/&OB) +                            */
     /*                           MODULE(*PGM) +                            */
     /*                           BNDSRVPGM(&LI/EXPJRNECU) +                */
     /*                           ACTGRP(*CALLER);                          */
     /*   >>CMD<<    DLTMOD       MODULE(&LI/&OB);                          */
     /* >>END-PRE-COMPILER<<                                                */
     /* =================================================================== */
             PGM        PARM(&I_OBJ           +
                             &I_FROMDATE      +
                             &I_FROMTIME      +
                             &I_TODATE        +
                             &I_TOTIME        +
                             &I_OBJTYPE       +
                             &I_MBR           +
                             &I_OUTFILE       +
                             &I_MBROPT        +
                             &I_CRTFILE       +
                             &I_TPLFILE       +
                             &I_OUTFILFM      +
                             &I_JRN           +
                             &I_RCVRNG        +
                             &I_SIZE          +
                             &I_LVLCHK        +
                             &I_MSGF          )

/* Input parameters     */
             DCL        VAR(&I_OBJ     ) TYPE(*CHAR) LEN(20)
             DCL        VAR(&I_FROMDATE) TYPE(*CHAR) LEN( 7)
             DCL        VAR(&I_FROMTIME) TYPE(*CHAR) LEN( 6)
             DCL        VAR(&I_TODATE  ) TYPE(*CHAR) LEN( 7)
             DCL        VAR(&I_TOTIME  ) TYPE(*CHAR) LEN( 6)
             DCL        VAR(&I_OBJTYPE ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&I_MBR     ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&I_OUTFILE ) TYPE(*CHAR) LEN(20)
             DCL        VAR(&I_MBROPT  ) TYPE(*CHAR) LEN(22)
             DCL        VAR(&I_CRTFILE ) TYPE(*CHAR) LEN( 1)
             DCL        VAR(&I_TPLFILE ) TYPE(*CHAR) LEN(20)
             DCL        VAR(&I_OUTFILFM) TYPE(*CHAR) LEN(10)
             DCL        VAR(&I_JRN     ) TYPE(*CHAR) LEN(20)
             DCL        VAR(&I_RCVRNG  ) TYPE(*CHAR) LEN(42)
             DCL        VAR(&I_SIZE    ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&I_LVLCHK  ) TYPE(*CHAR) LEN( 1)
             DCL        VAR(&I_MSGF    ) TYPE(*CHAR) LEN(10)

/* Temp. fields         */
             DCL        VAR(&OUTFILE   ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&OUTLIB    ) TYPE(*CHAR) LEN(10)

             DCL        VAR(&OBJ       ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&LIB       ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&OBJTYPE   ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&ACTIVE    ) TYPE(*CHAR) LEN( 1)
             DCL        VAR(&JRN       ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&JRNLIB    ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&IMAGES    ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&OMTJRNE   ) TYPE(*CHAR) LEN(10)

  /* ------------------------------------------------------------------------ */
  /*    Get selected (journaled) object from entry parameters.                */
  /* ------------------------------------------------------------------------ */
             CHGVAR     VAR(&OBJ    )   VALUE(%SST(&I_OBJ   1 10))
             CHGVAR     VAR(&LIB    )   VALUE(%SST(&I_OBJ  11 10))
             CHGVAR     VAR(&OBJTYPE)   VALUE(&I_OBJTYPE)

             /* Resolve object library */
             RTVOBJD    OBJ(&LIB/&OBJ) OBJTYPE(&OBJTYPE) RTNLIB(&LIB)

  /* ------------------------------------------------------------------------ */
  /*    Get output file and library from entry parameters.                    */
  /* ------------------------------------------------------------------------ */
             CHGVAR     VAR(&OUTFILE   ) VALUE(%SST(&I_OUTFILE  1 10))
             CHGVAR     VAR(&OUTLIB    ) VALUE(%SST(&I_OUTFILE 11 10))

  /* ------------------------------------------------------------------------ */
  /*    Get output file and library from entry parameters.                    */
  /* ------------------------------------------------------------------------ */
             CHGVAR     VAR(&OBJ    )   VALUE(%SST(&I_OBJ   1 10))
             CHGVAR     VAR(&LIB    )   VALUE(%SST(&I_OBJ  11 10))

  /* ------------------------------------------------------------------------ */
  /*    Restrict output file to *DFT.                                         */
  /* ------------------------------------------------------------------------ */
             IF         COND(&OUTFILE *NE '*DFT') THEN(DO)
               SNDPGMMSG  MSGID(CPD0006) MSGF(*LIBL/QCPFMSG) +
                            MSGDTA('0000' *CAT +
                            'Output file is restricted to *DFT.') +
                            TOPGMQ(*PRV (*)) MSGTYPE(*DIAG)
               GOTO       CMDLBL(CANCEL)
             ENDDO

  /* ------------------------------------------------------------------------ */
  /*    Restrict output library to QTEMP.                                     */
  /* ------------------------------------------------------------------------ */
             IF         COND(&OUTLIB *NE 'QTEMP') THEN(DO)
               SNDPGMMSG  MSGID(CPD0006) MSGF(*LIBL/QCPFMSG) +
                            MSGDTA('0000' *CAT +
                            'Output library is restricted to QTEMP.') +
                            TOPGMQ(*PRV (*)) MSGTYPE(*DIAG)
               GOTO       CMDLBL(CANCEL)
             ENDDO

  /* ------------------------------------------------------------------------ */
  /*    Restrict 'Create outfile' to *NO.                                     */
  /* ------------------------------------------------------------------------ */
             IF         COND(&I_CRTFILE *NE 'N') THEN(DO)
               SNDPGMMSG  MSGID(CPD0006) MSGF(*LIBL/QCPFMSG) +
                            MSGDTA('0000' *CAT +
                            'Parameter ''Create outfile'' is restricted to *NO.') +
                            TOPGMQ(*PRV (*)) MSGTYPE(*DIAG)
               GOTO       CMDLBL(CANCEL)
             ENDDO

  /* ------------------------------------------------------------------------ */
  /*    Check the selected journal.                                           */
  /* ------------------------------------------------------------------------ */
             CALLPRC    PRC('EXPJRNER7_rtvJrnInf') +
                          PARM(&OBJ       +
                               &LIB       +
                               &OBJTYPE   +
                               &OBJ       +
                               &LIB       +
                               &ACTIVE    +
                               &JRN       +
                               &JRNLIB    +
                               &IMAGES    +
                               &OMTJRNE   )

             IF         COND(&JRNLIB *EQ 'FOO' *AND +
                             &JRN    *EQ 'BAA') THEN(DO)
               SNDPGMMSG  MSGID(CPD0006) MSGF(*LIBL/QCPFMSG) +
                            MSGDTA('0000' *CAT +
                            'Exporting journal entries from journal ' *CAT +
                            &JRNLIB *TCAT '/' *CAT &JRN *BCAT +
                            'is not allowed.') +
                            TOPGMQ(*PRV (*)) MSGTYPE(*DIAG)
               GOTO       CMDLBL(CANCEL)
             ENDDO

  /* ------------------------------------------------------------------------ */
  /*    Heureca! Everything is fine!                                          */
  /* ------------------------------------------------------------------------ */
             RETURN

  /* ------------------------------------------------------------------------ */
  /*    Cancel command execution due to a validity checking issue.            */
  /* ------------------------------------------------------------------------ */
  CANCEL:
               SNDPGMMSG  MSGID(CPF0002) MSGF(*LIBL/QCPFMSG) +
                            TOPGMQ(*PRV (*)) MSGTYPE(*ESCAPE)

             ENDPGM

      /if not defined(fileInfDS_t)
      /define fileInfDS_t
      // =============================================================
      //   File information data structure
      // =============================================================
     d fileInfDS_t     ds                  based(pDummy)   qualified
      // Reserved 01
     d  reserved_01            1      8a
      // Open indication 1=open
     d  isOpen                 9      9a
      // End of file 1=EOF
     d  isEOF                 10     10a
      // Status
     d  status                11     15s 0
      // Operation code, first 5 pos.
     d  opCode                16     20a
      // IO-Type:
      //   F=The last operation was specified for a file name
      //   R=The last operation was specified for a record
      //   I=The last operation was an implicit file operation.
     d  IO_type               21     21a
      // Routine of operation code
     d  routine               22     29a
      // RPG source listing line nbr
     d  srcSeq                30     37a
      // Record format
     d  rcdFormat             38     45a
      // System message number
     d  sysMsgNbr             46     52a
      // Reserved 02
     d  reserved_02           53     66a

      // Valid after post:
      //    Screen size (product of the number of rows
      //    and the number of columns on the device screen).
     d  screenSize            67     70s 0
      //    The display's keyboard type.
      //       00 = alphanumeric or katakana
      //       10 = ideographic
     d  kbdType               71     72s 0
      //    The display type.
      //       00 = alphanumeric or katakana
      //       10 = ideographic
      //       20 = DBCS
     d  displayType           73     74s 0
      //    Always set to 00.
     d  mode                  75     76s 0
      // Reserved_03
     d  reserved_03           77     80a

      // -------------------------------
      //   Open Feedback
      // -------------------------------
     d  openFeedback                       likeds(openFeedback_t)

      // -------------------------------
      //   Input/Output Feedback
      // -------------------------------
     d  IO_feedback                        likeds(IO_feedback_t )

      // -------------------------------
      //   I/O Feedback, File specific
      // -------------------------------
     d  IO_feedback_file...
     d                              256a
      // I/O Feedback Database File
     d  IO_feedback_DB...
     d                                     likeds(IO_feedback_DB_t)
     d                                     overlay(IO_feedback_file)

      // -------------------------------
      //   Open Feedback
      // -------------------------------
     d openFeedback_t...
     d                 ds           160    qualified
      // DS=Display DB=File SP=Spooled File
     d  ODP_type               1      2a
      // File name
     d  file                   3     12a
      // Library
     d  lib                   13     22a
      // Spool file name
     d  spoolFile             23     32a
      // Spool file library
     d  spoolLib              33     42a
      // Spool file number
     d  spoolNbr              43     44i 0
      // Record length
     d  maxRcdLength          45     46i 0
      // Key length
     d  maxKeyLength          47     48i 0
      // Member
     d  mbr                   49     58a
      // Reserved
     d  reserved_01           59     62i 0
      // Reserved
     d  reserved_02           63     66i 0
      // File type
      //     1  =  Display
      //     2  =  Printer
      //     4  =  Diskette
      //     5  =  Tape
      //     9  =  Save
      //    10  =  DDM
      //    11  =  ICF
      //    20  =  Inline data
      //    21  =  Database
     d  fileType              67     68i 0
      // Reserved
     d  reserved_03           69     71a
      // Number of lines on a display screen or       (Display, printer)
      // number of lines on a printed page.
     d  rows                  72     73i 0
      // Length of the null field byte map.           (Database)
     d  lenNullFldMap         72     73i 0
      // Number of positions on a display screen or   (Display, printer)
      // number of characters on a printed line.
     d  columns               74     75i 0
      // Length of the null key field byte map.       (Database)
     d  lenKeyFldMap          74     75i 0
      // Number of records in the member at open
      // at open time.
     d numRcdsAtOpen          76     79i 0
      // Access type
     d accessType             80     81a
      // Duplicate key?
     d isDupKey               82     82a
      // Source file?
     d isSrcFile              83     83a
      // Reserved
     d reserved_04            84     93a
      // Reserved
     d reserved_05            94    103a
      // Offset to volume label fields of open
      // feedback area.
     d ofsVolLblFld          104    105i 0
      // Max rcds in blk
     d maxBlkRcds            106    107i 0
      // Overflow line
     d overflow              108    109i 0
      // Blk increment
     d blkInc                110    111i 0
      // Reserved
     d reserved_06           112    115a
      // Miscellaneous flags
     d flags1                116    116a
      // Requester name
     d requester             117    126a
      // Open count
     d openCount             127    128i 0
      // Reserved
     d reserved_07           129    129a
      // Num based mbrs
     d numBasedMbrs          131    132i 0
      // Miscellaneous flags
     d flags2                133    133a
      // Open identifier
     d openID                134    135a
      // Max rcd fmt length
     d maxRcdFmtLen          136    137i 0
      // Database CCSID
     d CCSID                 138    139i 0
      // Miscellaneous flags
     d flags3                140    140a
      // Reserved
     d reserved_08           141    146a
      // Num devs defined
     d numDevices            147    148i 0

      // -------------------------------
      //   Input/Output Feedback
      // -------------------------------
     d IO_feedback_t...
     d                 ds           126    qualified
      // Offset to file dependant feedback
     d ofsFileDepFB            1      2i 0
      // Write count
     d writeCount              3      6i 0
      // Read count
     d readCount               7     10i 0
      // Write/read count
     d writeReadCount         11     14i 0
      // Other I/O count
     d otherCount             15     18i 0
      // Reserved
     d reserved_01            19     19a
      // Current operation
      //   hex 01 =  Read or read block or read from invited devices
      //   hex 02 =  Read direct
      //   hex 03 =  Read by key
      //   hex 05 =  Write or write block
      //   hex 06 =  Write-read
      //   hex 07 =  Update
      //   hex 08 =  Delete
      //   hex 09 =  Force-end-of-data
      //   hex 0A =  Force-end-of-volume
      //   hex 0D =  Release record lock
      //   hex 0E =  Change end-of-data
      //   hex 0F =  Put deleted record
      //   hex 11 =  Release device
      //   hex 12 =  Acquire device
     d operation              20     20a
      // Rcd format name
     d IO_rcdFmt              21     30a
      // Device class
     d deviceClass            31     32a
      // Pgm device name
     d IO_pgmDevice           33     42a
      // Rcd len of I/O
     d IO_rcdLength           43     46i 0
      // Reserved
     d reserved_02            47    126a

      // -------------------------------
      //   I/O Feedback Database File
      // -------------------------------
     d IO_feedback_DB_t...
     d                 ds                  qualified
      // Number of locked records
     d  numLckRcds            11     12i 0
      // Maximum number of fields
     d  maxNumFlds            13     14i 0
      // Nbr of key fields
     d  nbrOfKeyFlds          21     22i 0
      // Key length
     d  keyLength             27     28i 0
      // Data member number.
     d  dtaMbrNum             29     30i 0
      // Relative record number in data member.
     d  rcdNbr                31     34u 0

      /endif

/if not defined(JRNETYPES) /define JRNETYPES
// -------------------------------------------------- // Layouts for var.-length portion of journal entries // --------------------------------------------------
// -------------------------------------------------- // Data area // --------------------------------------------------
// Common data area journal entry d jrnEType_e_t... d ds qualified based(pDummy) d start 10i 0 d length 10i 0 d decPos 10i 0 d offset 10i 0 d type 10a
// Update data area (E EA, E EB) journal entries d jrnEType_e_ea_t... d ds qualified based(pDummy) d start 10i 0 d length 10i 0 d decPos 10i 0 d offset 10i 0 d type 10a // padding char (*) // value char (*)
d jrnEType_e_eb_t... d ds likeds(jrnEType_e_ea_t) based(pDummy)
// Create data area (E EE) journal entry d jrnEType_e_ee_t... d ds qualified based(pDummy) d crtTmstmp 8a d dtaAra_name 10a d dtaAra_lib 10a d type 5a d reserved_1 3a d numE 10i 0 d length 10i 0 d decPos 10i 0 d curLength 10i 0 d value 2000a d pubAuth 10a d text 50a d owner 10a d objExistAuth 1a d objMgtAuth 1a d objOprAuth 1a d reserved_2 1a d authListMgt 1a d readAuth 1a d addAuth 1a d updAuth 1a d delAuth 1a d exclAuth 1a d execAuth 1a d objAltAuth 1a d objRefAuth 1a d resultAuth 10a
// -------------------------------------------------- // Data queue // --------------------------------------------------
// Common data queue journal entry d jrnEType_q_t... d ds qualified based(pDummy) d sysInf_1 16a d sysInf_2 2a d sysInf_3 10a d order 2a d keyLength 10i 0 d dataLength 10i 0 d apiInf 16a // key char (*) // data char (*)
// Send data queue, has key (Q QK) journal entry d jrnEType_q_qk_t... d ds qualified based(pDummy) d dataLength 10i 0 d ofsData 10i 0 d reserved_1 2a d keyLength 5i 0 d reserved_2 4a // key char (*) // padding char (*) // data char (*)
// Received data queue, has key (Q QL) journal entry d jrnEType_q_ql_t... d ds qualified based(pDummy) d sysInf_1 16a d sysInf_2 2a d keyLength 5i 0 d order 2a // key char (*)
// Data queue cleared, has key (Q QJ) journal entry d jrnEType_q_qj_t... d ds qualified based(pDummy) d reserved_1 2a d keyLength 5i 0 d order 2a // key char (*)
// Send data queue, no key (Q QS) journal entry d jrnEType_q_qs_t... d ds qualified based(pDummy) d sysInf_1 16a d sysInf_2 2a d sysInf_3 10a d dataLength 10i 0 // data char (*)
// Receive data queue entry, no key (Q QR) d jrnEType_q_qr_t... d ds qualified based(pDummy) d sysInf_1 16a d sysInf_2 2a
// Clear data queue entry, no key (Q QC) d jrnEType_q_qc_t... d ds qualified based(pDummy) d sysInf_2 2a
/endif

/if not defined(QMHQRDQD) /define QMHQRDQD
// Retrieve Data Queue Description (QMHQRDQD) API d QMHQRDQD... d pr extpgm('QMHQRDQD') d o_rcvVar 65535a options(*varsize) d i_lenRcvVar 10i 0 const d i_format 8a const d i_qDtaQ 20a const
